import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, CircleGeometry, BoxGeometry } = THREE;

  const root = new Group();
  root.name = 'collection-card-2';

  const ownedGeometries = [];
  const ownedMaterials = [];
  const loadedTextures = [];
  let disposed = false;

  const makeBasicMaterial = (options = {}) => {
    const material = new MeshBasicNodeMaterial(options);
    ownedMaterials.push(material);
    return material;
  };

  const backdropMaterial = makeBasicMaterial();
  const backdropY = uv().y;
  const lowerGradient = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.114),
    smoothstep(0.0, 0.58, backdropY)
  );
  backdropMaterial.colorNode = mix(
    lowerGradient,
    vec3(0.055, 0.055, 0.067),
    smoothstep(0.58, 1.0, backdropY)
  );

  const backdropGeometry = new PlaneGeometry(7, 6);
  ownedGeometries.push(backdropGeometry);
  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.name = 'engineered-gradient-backdrop';
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  const shadowGeometry = new CircleGeometry(1, 64);
  ownedGeometries.push(shadowGeometry);
  const shadowMaterial = makeBasicMaterial({
    color: '#0b0b10',
    transparent: true,
    opacity: 0.48,
    depthWrite: false
  });
  const shadow = new Mesh(shadowGeometry, shadowMaterial);
  shadow.name = 'contact-shadow';
  shadow.position.set(0, -1.18, -0.08);
  shadow.scale.set(2.0, 0.42, 1);
  root.add(shadow);

  const cardGeometry = new PlaneGeometry(4.9, 3.05);
  ownedGeometries.push(cardGeometry);
  const cardMaterial = makeBasicMaterial({
    color: '#16161d',
    transparent: true,
    opacity: 0.94
  });
  const card = new Mesh(cardGeometry, cardMaterial);
  card.name = 'machined-surface';
  card.position.set(0, 0.05, -0.02);
  root.add(card);

  const imageGeometry = new PlaneGeometry(4.72, 2.95);
  ownedGeometries.push(imageGeometry);
  const imageMaterial = makeBasicMaterial({
    color: '#e8ecf2',
    transparent: true,
    opacity: 0.98
  });
  const image = new Mesh(imageGeometry, imageMaterial);
  image.name = 'collection-card-image';
  image.position.set(0, 0.05, 0.04);
  root.add(image);

  const accentGeometry = new BoxGeometry(0.72, 0.035, 0.025);
  ownedGeometries.push(accentGeometry);
  const accentMaterial = makeBasicMaterial({
    color: '#ff2a38'
  });
  const accent = new Mesh(accentGeometry, accentMaterial);
  accent.name = 'signal-red-accent';
  accent.position.set(-1.82, -1.38, 0.12);
  root.add(accent);

  const edgeGeometry = new BoxGeometry(0.035, 2.56, 0.025);
  ownedGeometries.push(edgeGeometry);
  const edge = new Mesh(edgeGeometry, accentMaterial);
  edge.name = 'card-edge-accent';
  edge.position.set(2.34, 0.05, 0.12);
  root.add(edge);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (disposed) return;
      loadedTextures.push(texture);
      if (THREE.SRGBColorSpace) texture.colorSpace = THREE.SRGBColorSpace;
      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const material of ownedMaterials) {
      material.dispose();
    }

    for (const geometry of ownedGeometries) {
      geometry.dispose();
    }

    for (const texture of loadedTextures) {
      if (texture && texture.dispose) texture.dispose();
    }

    root.userData.handlers = {};
  };

  return root;
}
